(3852569, 546222, 75328, '<td valign="top">nice silhous.<br/>look at the muscles at work</td>', 'nice silhous.look at the muscles at work', '2007-07-01 02:42:51.000000', NULL, 1),
(3852572, 546110, 77397, '<td valign="top">I think I''ve seen this shot before--- very nice.</td>', 'I think I''ve seen this shot before--- very nice.', '2007-07-01 02:43:31.000000', NULL, 1),
(3852575, 532059, 47487, '<td valign="top">nice frame-filling shot. The halter actually adds to the picture.</td>', 'nice frame-filling shot. The halter actually adds to the picture.', '2007-07-01 02:47:22.000000', NULL, 1),
(3852578, 545917, 47487, '<td valign="top">Interesting idea. I love the green around the window.</td>', 'Interesting idea. I love the green around the window.', '2007-07-01 02:48:16.000000', NULL, 1),
(3852581, 545337, 47487, '<td valign="top">lovely, lovely shot. Brilliantly composed.</td>', 'lovely, lovely shot. Brilliantly composed.', '2007-07-01 02:48:56.000000', NULL, 1),
(3852582, 543991, 60915, '<td valign="top">Beautiful light and tones! Personally I''m not that keen on selective desat, but it seems to work here, I''m glad you kept it subtle. I think I would still prefer it without though. : )</td>', 'Beautiful light and tones! Personally I''m not that keen on selective desat, but it seems to work here, I''m glad you kept it subtle. I think I would still prefer it without though. : )', '2007-07-01 02:49:26.000000', NULL, 1),
(3852588, 529675, 47487, '<td valign="top">You know, I haven''t had a Hawaiian Punch in about fifteen years, but I can almost taste one now. :) <br/> <br/>As for this shot, it''s a clever idea and a good snapshot</td>', 'You know, I haven''t had a Hawaiian Punch in about fifteen years, but I can almost taste one now. :)  As for this shot, it''s a clever idea and a good snapshot', '2007-07-01 02:50:34.000000', NULL, 1),
(3852589, 545504, 60915, '<td valign="top">I like how it disappears into the clouds. Impressive structure well captured!</td>', 'I like how it disappears into the clouds. Impressive structure well captured!', '2007-07-01 02:50:45.000000', NULL, 1),
(3852591, 546119, 47487, '<td valign="top">nice composition featuring this very ordinary object. Good use of bokeh as negative space, if that''s even possible. :)</td>', 'nice composition featuring this very ordinary object. Good use of bokeh as negative space, if that''s even possible. :)', '2007-07-01 02:51:27.000000', NULL, 1),
(3852593, 545742, 47487, '<td valign="top">good light, interesting processing, just for some reason a little unexciting to me personally.</td>', 'good light, interesting processing, just for some reason a little unexciting to me personally.', '2007-07-01 02:52:50.000000', NULL, 1),
(3852595, 546230, 40718, '<td valign="top">wow!  Very impressed with the control of the picture.  10</td>', 'wow!  Very impressed with the control of the picture.  10', '2007-07-01 02:53:22.000000', NULL, 1),
(3852596, 545948, 16241, '<td valign="top">beautiful</td>', 'beautiful', '2007-07-01 02:53:25.000000', NULL, 1),
(3852597, 546218, 60915, '<td valign="top">I''ll bet this is getting hammered. :) <br/>I''m normally not into abstracts, but I find this image very pleasing!<br/>I think the colour and composition is excellent, great work! 7</td>', 'I''ll bet this is getting hammered. :) I''m normally not into abstracts, but I find this image very pleasing!I think the colour and composition is excellent, great work! 7', '2007-07-01 02:54:54.000000', NULL, 1),
(3852600, 542475, 47487, '<td valign="top">Nice subject, good composition, but I think the vignetting might be overdone just a tiny bit for my tastes. I like the color too.</td>', 'Nice subject, good composition, but I think the vignetting might be overdone just a tiny bit for my tastes. I like the color too.', '2007-07-01 02:58:34.000000', NULL, 1);
